const { data, error } = await authClient.oauth2.updateClient({
    client_id,
    update,
});
```

### Server Side

```ts
const data = await auth.api.updateOAuthClient({
    body: {
        client_id,
        update,
    },
    // This endpoint requires session cookies.
    headers: await headers()
});
```

